@endsection @push('scripts')<script>let row=0;const products=@json($products->map(fn($p)=>['id'=>$p->id,'name'=>$p->item_code.' — '.$p->name]));function addRow(){const i=row++;document.getElementById('items').insertAdjacentHTML('beforeend',`<tr><td><select class="form-select" name="items[${i}][product_id]" required><option value="">Choose product</option>${products.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></td><td><input class="form-control" type="number" min="0.0001" step="0.0001" value="1" name="items[${i}][quantity]" required></td><td><input class="form-control" type="number" min="0" step="0.01" name="items[${i}][unit_price]" required></td><td><button type="button" class="btn btn-outline-danger" onclick="this.closest('tr').remove()"><i class="bi bi-trash"></i></button></td></tr>`)}document.getElementById('add-row').onclick=addRow;addRow();</script>@endpush
